def chain_of_words(chain):
    tokens = chain[0]
    first = tokens[0]
    second = tokens[1]

    # Find the first occurrence of the second token
    for i in range(len(tokens)):
        if tokens[i] == second:
            break

    # Find the first occurrence of the first token
    for i in range(len(tokens)):
        if tokens[i] == first:
            break

    # Extract the tokens after the second token
    result = tokens[1:i]

    return ','.join(result)

